const $=id=>document.getElementById(id);
const instruments=[['Scalpel','A small cutting blade mounted on a handle.','scalpel|blade'],['Metzenbaum scissors','Long handles with slender, curved cutting blades.','metzenbaum|scissors'],['Hemostat','Ring handles, a ratchet lock, and narrow clamping jaws.','hemostat|clamp'],['Needle holder','Ring handles and short, robust jaws for holding a suture needle.','needle holder|needle driver'],['Tissue forceps','A tweezer-shaped instrument with opposed grasping tips.','forceps|tweezers']];
const anatomy=[['Liver','The large schematic structure in the right upper abdomen.'],['Spleen','The schematic structure in the left upper abdomen.'],['Stomach','The curved sac in the upper abdomen.'],['Small intestine','The central coiled structure.'],['Colon','The peripheral bowel outline surrounding the small intestine.']];
const sterile=Array.from({length:10},(_,i)=>({bad:i%2===0,answer:i%2===0?'Contamination is indicated: the marked instrument crosses the defined sterile boundary. Flag it and request replacement or re-establishment of the simulated field.':'No boundary breach is depicted in this schematic. This observation alone cannot establish real-world sterility.'}));
const workflows={trauma:[{state:'Initial team assessment is incomplete',next:'Confirm the team assessment and scenario information before selecting an operative workflow.',tools:'Assessment and monitoring resources depend on the scenario; the scripted case does not specify a surgical instrument yet.',risks:'Incomplete injury information and unrecognized instability. Request the missing scenario details.'},{state:'Assessment complete; operative plan not confirmed',next:'Confirm the operative objectives, team roles, required resources, and safety checks before proceeding.',tools:'Confirm availability of the planned instrument set, suction, and required simulation resources.',risks:'An unclear plan, unavailable resources, and communication failures.'},{state:'Simulated bleeding identified; reassessment pending',next:'Prioritize hemorrhage control within the approved simulation plan and reassess the response before advancing.',tools:'The simulation plan may require suction and hemostatic instruments; the exact choice needs injury and anatomy details.',risks:'Ongoing blood loss, obscured anatomy, and injury to adjacent structures. Do not infer an exact maneuver from this limited state.'}],closure:[{state:'Procedure objectives complete; final checks pending',next:'Complete a systematic final reassessment, confirm hemostasis, and reconcile instrument and sponge counts before closure readiness is confirmed.',tools:'Counting and inspection resources; closure instruments only after readiness is confirmed.',risks:'Retained items, unresolved bleeding, or missed injuries.'},{state:'Count discrepancy reported',next:'Pause closure progression, notify the team, and resolve the discrepancy under the simulation protocol.',tools:'Count records and the protocol-defined search resources.',risks:'A retained surgical item. An unresolved discrepancy prevents progression in this scripted workflow.'},{state:'Final checks and counts confirmed',next:'Confirm the planned closure and handoff with the team, then document completion and the ongoing reassessment plan.',tools:'The planned closure set; specific materials are not defined in this synthetic case.',risks:'Incomplete handoff and failure to communicate unresolved concerns.'}]};
let gate='A',category='instruments',index=0,logs=[],suiteRunning=false;
const svg=(content)=>`<svg viewBox="0 0 600 310" role="img" aria-label="Synthetic ${category} illustration"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#ffffff" opacity=".04"/></pattern></defs><rect width="600" height="310" fill="url(#grid)"/>${content}</svg>`;
function instrumentDrawing(i){const common='fill="none" stroke="#cbdce1" stroke-width="8" stroke-linecap="round"';let shape;if(i===0)shape=`<path d="M150 230L350 95" stroke="#bfd0d7" stroke-width="24"/><path d="M350 95L455 47Q447 104 368 114Z" fill="#ecf6f8"/>`;else if(i===4)shape=`<path d="M160 75Q270 100 445 208M160 75Q230 170 423 232" ${common}/>`;else shape=`<g ${common}><ellipse cx="185" cy="230" rx="32" ry="24"/><ellipse cx="270" cy="250" rx="32" ry="24"/><path d="M204 209L350 70M278 225L${i===3?'365 105':'395 57'}M270 145L350 70"/><circle cx="292" cy="166" r="8"/></g>${i===2?'<path d="M347 70L385 40" stroke="#cbdce1" stroke-width="5"/>':''}`;return svg(shape+`<text x="35" y="40" fill="#b4d5df" font-size="13">Reference ${i+1} / 5</text><circle cx="450" cy="160" r="17" fill="#e6ab55"/><text x="444" y="166" fill="#173b45" font-size="16">?</text>`)}
function anatomyDrawing(i){const colors=anatomy.map((_,n)=>n===i?'#efbd79':'#7396a0');return svg(`<path d="M205 25Q300 0 395 25L440 280H160Z" fill="#365f6c" stroke="#8aa6af"/><path d="M210 65Q315 30 330 100Q265 120 205 99Z" fill="${colors[0]}"/><ellipse cx="384" cy="89" rx="18" ry="31" fill="${colors[1]}"/><path d="M330 72Q380 75 361 133Q325 152 309 119Z" fill="${colors[2]}"/><path d="M240 157Q340 130 354 169Q220 172 250 190Q375 182 348 213Q228 205 260 234" fill="none" stroke="${colors[3]}" stroke-width="13"/><path d="M215 249V143H386V249" fill="none" stroke="${colors[4]}" stroke-width="18"/><text x="30" y="38" fill="#b4d5df" font-size="13">Schematic · anterior view</text><text x="30" y="280" fill="#efbd79" font-size="13">Identify the highlighted structure</text>`)}
function render(){category=$('category').value;let isB=gate==='B';$('category').hidden=isB;$('categoryLabel').hidden=isB;$('scenarioBox').hidden=!isB;let data=category==='instruments'?instruments:anatomy;$('sceneTitle').textContent=isB?'Workflow state':category==='instruments'?'Instrument recognition':category==='anatomy'?'Anatomy recognition':'Sterile field assessment';$('sceneCount').textContent=isB?'Synthetic oral-board case':'Synthetic reference scene';if(isB){let states=workflows[$('scenario').value];$('scene').innerHTML=svg(`<rect x="60" y="70" width="480" height="170" rx="10" fill="#355f6b" stroke="#7fadb7"/><text x="90" y="108" fill="#9fc5cd" font-size="15">Current simulation state</text><foreignObject x="90" y="125" width="420" height="100"><div xmlns="http://www.w3.org/1999/xhtml" style="font:24px Avenir, sans-serif;color:white">${states[$('state').selectedIndex].state}</div></foreignObject>`);$('question').value='What is the next step, what resources are required, and what risks should be considered?'}else if(category==='sterility'){$('scene').innerHTML=svg(`<rect x="110" y="45" width="380" height="225" fill="#287c83" stroke="#b4e0db" stroke-width="3" stroke-dasharray="8 7"/><text x="135" y="80" fill="#d5eeea" font-size="14">Defined sterile boundary</text><path d="M${sterile[index%10].bad?'425 190L535 245':'245 190L360 235'}" stroke="#e6edf0" stroke-width="13"/><circle cx="${sterile[index%10].bad?490:300}" cy="220" r="30" fill="none" stroke="#efbd79" stroke-width="2"/><text x="30" y="300" fill="#b4d5df" font-size="13">Boundary case ${index%10+1} / 10</text>`);$('question').value='Is the marked instrument within the sterile boundary, or is contamination indicated?'}else{$('scene').innerHTML=category==='instruments'?instrumentDrawing(index%5):anatomyDrawing(index%5);$('question').value=category==='instruments'?'Identify the instrument shown.':'Identify the highlighted anatomical structure.'}$('caption').textContent=isB?'The engine uses this explicit state and the question category to select a bounded response.':'Illustrations are selected from known metadata. Recognition here demonstrates the interface and response pipeline, not computer vision.';$('sceneControls').innerHTML='';if(!isB){(category==='sterility'?sterile:data).forEach((x,n)=>{let b=document.createElement('button');b.textContent=category==='sterility'?`Case ${n+1}`:`Sample ${n+1}`;b.onclick=()=>{index=n;render()};if(n===index%(category==='sterility'?10:5))b.style.borderColor='#006e78';$('sceneControls').append(b)})}}
function fillStates(){$('state').innerHTML='';workflows[$('scenario').value].forEach(x=>{let o=document.createElement('option');o.textContent=x.state;$('state').append(o)});render()}
function resolve(q){q=q.toLowerCase();if(gate==='B'){let s=workflows[$('scenario').value][$('state').selectedIndex];let parts=[];if(/next|step|workflow|plan|proceed/.test(q))parts.push(s.next);if(/instrument|tool|resource|requir/.test(q))parts.push(s.tools);if(/risk|patholog|sign|concern/.test(q))parts.push(s.risks);return parts.length?{answer:parts.join(' '),coverage:'Matched scripted workflow'}:{answer:'This question is outside the demo workflow categories. Ask about next steps, instruments or resources, or risks. Additional clinical context is required.',coverage:'Abstained'}}if(!/identify|what|name|which|steril|contamin|recogn|boundary|shown|highlight/.test(q))return{answer:'Question outside the supported recognition prompts. Ask to identify the displayed instrument or anatomy, or assess the marked sterile boundary.',coverage:'Abstained'};if(category==='sterility')return{answer:sterile[index%10].answer,coverage:'Known boundary metadata'};let item=(category==='instruments'?instruments:anatomy)[index%5];let nameRequest=q.match(/(?:where is|locate|find|show me) (.+)/);if(nameRequest&&!item[0].toLowerCase().includes(nameRequest[1].replace(/[?.]/g,'')))return{answer:'The requested target is not established in this single-object reference scene. Select the appropriate sample.',coverage:'Abstained'};return{answer:`${item[0]}. ${item[1]}`,coverage:'Known scene metadata'}}
function speak(text){if($('audio').checked&&'speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(text))}}
function answer(quiet=false){let q=$('question').value.trim();if(!q){$('speechStatus').textContent='Enter or dictate a question first.';return}let t=performance.now(),r=resolve(q),ms=+(performance.now()-t).toFixed(2);let entry={gate:'1'+gate,category:gate==='B'?$('scenario').value:category,scene:gate==='B'?$('state').value:index+1,question:q,...r,engineLatencyMs:ms,timestamp:new Date().toISOString()};logs.push(entry);$('response').replaceChildren();let label=document.createElement('span');label.className='responseLabel';label.textContent='System response · '+r.coverage;let p=document.createElement('p');p.textContent=r.answer;let metric=document.createElement('span');metric.className='metric';metric.textContent=`${ms} ms local rule lookup · speech duration excluded · no model confidence`; $('response').append(label,p,metric);drawLogs();if(!quiet)speak(r.answer);return entry}
function drawLogs(){$('stats').textContent=`${logs.length} responses · ${logs.filter(x=>x.coverage==='Abstained').length} abstentions`;$('records').replaceChildren();logs.slice().reverse().forEach(x=>{let d=document.createElement('div');d.className='record';let badge=document.createElement('b');badge.textContent=x.gate;let body=document.createElement('div');body.textContent=x.question;let p=document.createElement('p');p.textContent=x.answer;body.append(p);let time=document.createElement('small');time.textContent=x.engineLatencyMs+' ms';d.append(badge,body,time);$('records').append(d)})}
function setGate(g){gate=g;['A','B','T'].forEach(x=>$('tab'+x).classList.toggle('active',x===g));$('workspace').hidden=g==='T';$('tech').hidden=g!=='T';if(g!=='T')render()}
$('tabA').onclick=()=>setGate('A');$('tabB').onclick=()=>setGate('B');$('tabT').onclick=()=>setGate('T');$('category').onchange=()=>{index=0;render()};$('scenario').onchange=fillStates;$('state').onchange=render;$('answer').onclick=()=>answer();$('next').onclick=()=>{if(gate==='B')$('state').selectedIndex=($('state').selectedIndex+1)%$('state').length;else index=(index+1)%(category==='sterility'?10:5);render()};$('suite').onclick=()=>{if(gate==='A'){for(const c of ['instruments','anatomy','sterility']){$('category').value=c;for(index=0;index<(c==='sterility'?10:5);index++){render();answer(true)}}index=0;render()}else{for(const s of ['trauma','closure']){$('scenario').value=s;fillStates();for(let n=0;n<$('state').length;n++){$('state').selectedIndex=n;render();answer(true)}}} $('speechStatus').textContent='Example suite recorded. These are scripted coverage checks, not independent accuracy measurements.'};$('clear').onclick=()=>{logs=[];drawLogs()};$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({demo:'Surgical Gates Lab',engine:'deterministic scene metadata and state rules',officialScoring:false,records:logs},null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='surgical-gates-session.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;$('mic').onclick=()=>{if(!Recognition){$('speechStatus').textContent='Speech input is unavailable in this browser. Type the question instead.';return}let rec=new Recognition();rec.lang='en-US';rec.onresult=e=>{$('question').value=e.results[0][0].transcript;$('speechStatus').textContent='Transcribed. Review the question, then run the answer.'};rec.onerror=e=>$('speechStatus').textContent='Microphone: '+e.error+'. You can type instead.';rec.onend=()=>$('mic').disabled=false;try{rec.start();$('mic').disabled=true;$('speechStatus').textContent='Listening… Browser speech processing may use its provider’s service.'}catch(e){$('speechStatus').textContent='Could not start microphone. Type the question instead.'}};
$('tech').innerHTML=`<h2>What this demo implements</h2><table><tr><th>Requirement</th><th>Demo coverage</th></tr><tr><td>1A: instruments and anatomy</td><td>Five schematic instruments and five anatomy structures, answered from scene metadata.</td></tr><tr><td>1A: sterile fields</td><td>Ten synthetic boundary cases. No visual sterility inference.</td></tr><tr><td>1A: verbal questions, audible answers</td><td>Optional browser dictation and text-to-speech; typed input always available.</td></tr><tr><td>1B: workflow and next steps</td><td>Two illustrative cases, six explicit states, resource and risk responses, and abstention for unsupported questions.</td></tr></table><h3>Technology running here</h3><p>Buildless HTML, responsive CSS, vanilla JavaScript, and inline SVG. A deterministic local rule engine maps selected scene metadata and workflow states to responses. Web Speech APIs provide optional speech input and synthesized output. Session evidence stays in page memory and exports as JSON. Cloudflare static hosting is delivered through Sites. No API key, backend, model inference, or database is used.</p><h3>Path to an actual Gate 1 system</h3><p>Replace metadata lookup with a locally hosted vision-language model and calibrated instrument/anatomy detection, connect camera frames, use local speech recognition and speech synthesis, and add a surgeon-reviewed retrieval corpus and workflow state model. Benchmark unseen scenes and questions with independent surgeon scoring, end-to-end latency, uncertainty and abstention tracking. The competition restricts remote networking; this browser demo is not a competition deployment architecture.</p><h3>Scope and evidence</h3><p>The rules specify complete autonomy for the medical knowledge examination, 5 instruments and 5 anatomy identifications with audible responses for the 1A minimum, and anticipation of subsequent workflow steps for 1B. This app uses a provisional example set because the official lists are TBD in rules v1.0. Timing measures only local rule evaluation; it is not official efficiency scoring. Content is illustrative and requires clinical review before use in an assessment. This is not a clinical decision tool or a claim of DARPA qualification.</p><p><a href="https://www.darpa.mil/sites/default/files/attachment/2026-09/darpa-competition-surgical-rules.pdf">Read the source rules, pages 16 and 18</a></p>`;fillStates();
